namespace KitX.ToolKit.Time;

/// <summary>The process default id generator: GUIDs in "N" format.</summary>
/// <remarks>
/// <para>"N" (32 hex digits, no dashes) is what the pre-rewrite code produced at all three call
/// sites, so this preserves the observable id shape.</para>
/// <para>Flow ids and ToolKit ids are both GUIDs today but are generated by separate methods on
/// purpose: if a future ToolKit id needs to be human-readable, only <see cref="NewToolkitId"/>
/// changes and no flow id is affected.</para>
/// </remarks>
internal sealed class GuidIdGenerator : IIdGenerator
{
    /// <summary>Shared instance; the type holds no state.</summary>
    public static readonly GuidIdGenerator Instance = new();

    private GuidIdGenerator()
    {
    }

    /// <inheritdoc/>
    public string NewFlowId() => Guid.NewGuid().ToString("N");

    /// <inheritdoc/>
    public string NewToolkitId() => Guid.NewGuid().ToString("N");
}
